cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# enumerate candidate squares and Ls
sq=[]
for r in range(6):
 for c in range(6):
  s={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if s<=cells:sq.append(s)
L=[]
for r in range(6):
 for c in range(6):
  for missing in [(0,0),(0,1),(1,0),(1,1)]:
   s={(r+i,c+j) for i in (0,1) for j in (0,1)}-{(r+missing[0],c+missing[1])}
   if s<=cells:L.append(s)
sol=[]
for s in sq:
 def back(rem,chosen):
  if not rem:
   sol.append((s,chosen));return
  x=min(rem)
  for l in L:
   if x in l and l<=rem:back(rem-l,chosen+[l])
 back(cells-s,[])
len(sq),len(sol),sq
